    this.style = {};
    this.dataset = {};
    this.children = [];
    this.textContent = "";
    this.innerHTML = "";
    this.id = "";
    this.offsetWidth = 40;
  }

  appendChild(child) {
    this.children.push(child);
    return child;
  }

  contains(target) {
    if (target === this) return true;
    return this.children.some((child) => child?.contains?.(target));
  }

  getBoundingClientRect() {
    return { left: 0, top: 0, width: 40, height: 40 };
  }
}

